-- schema.ts has .unique() on knowledge_avatars.handle; align DB name to drizzle's expectation.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='knowledge_avatars_handle_key') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='knowledge_avatars_handle_unique') THEN ALTER TABLE "knowledge_avatars" RENAME CONSTRAINT "knowledge_avatars_handle_key" TO "knowledge_avatars_handle_unique"; END IF; END $$;
-- conversations.linked_market_id FK now declared in schema.ts; align DB name.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='conversations_linked_market_id_fkey') AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='conversations_linked_market_id_prediction_markets_id_fk') THEN ALTER TABLE "conversations" RENAME CONSTRAINT "conversations_linked_market_id_fkey" TO "conversations_linked_market_id_prediction_markets_id_fk"; END IF; END $$;
-- knowledge_avatars had BOTH handle_key and handle_unique (duplicate UNIQUE on handle); drop the redundant psql-named one.
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='knowledge_avatars_handle_key') AND EXISTS (SELECT 1 FROM pg_constraint WHERE conname='knowledge_avatars_handle_unique') THEN ALTER TABLE "knowledge_avatars" DROP CONSTRAINT "knowledge_avatars_handle_key"; END IF; END $$;
